def parse_cron_field(field, lo, hi):
    result = set()
    for part in field.split(','):
        step = 1
        if '/' in part:
            base, step_str = part.split('/')
            step = int(step_str)
        else:
            base = part

        if base == '*':
            start, end = lo, hi
        elif '-' in base:
            start_str, end_str = base.split('-')
            start, end = int(start_str), int(end_str)
        else:
            start = end = int(base)

        if start < lo or end > hi or start > end:
            raise ValueError(f"Invalid range in field: {part}")

        for val in range(start, end + 1, step):
            result.add(val)

    return sorted(result)
